for _ in range(int(input())):
    start, finish = map(int, input().split())
    if finish % start:
        print(0)
        continue
    value = finish // start
    count = 1
    # The gcd is square-free and contains precisely the small prime divisors.
    small = gcd(value, SMALL_PRODUCT)
    divisor = 2
    while divisor * divisor <= small:
        if small % divisor == 0:
            small //= divisor
            while value % divisor == 0:
                value //= divisor
                count += 1
        divisor += 1 if divisor == 2 else 2
    if small > 1:
        while value % small == 0:
            value //= small
            count += 1
    if value == 1:
        print(count)
        continue
    # The remaining factors exceed 1000, so there can be at most two.
    if value <= SMALL_PAIR_BOUND:
        print(count + 1)
        continue
    print(count + 1 + (gcd(value, LARGE_PRODUCT) > 1))
